#[derive(Subcommand, Debug)]
pub enum EntryAction {
    /// Summarize billable time for invoicing, grouped by project.
    #[command(after_long_help = "\
Examples:
  toggl entry invoice
  toggl entry invoice --since 2026-01-01 --until 2026-01-31")]
    Invoice {
        #[arg(long, help = "Filter time entries starting on or after this date/time")]
        since: Option<String>,
        #[arg(long, help = "Filter time entries before this date/time")]
        until: Option<String>,
    },
    /// Show the currently running time entry.
    #[command(
        name = "running",
        alias = "current",
        after_long_help = "\
Examples:
  toggl entry running             Show the running entry
  toggl entry running --json      Show the running entry as JSON

Note: JSON output includes a \"running\": true field for active entries."
    )]
    Current {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// List time entries.
    #[command(after_long_help = "\
use crate::api::client::ApiClient;
use crate::models::ResultWithDefaultError;
use crate::utilities;
use std::collections::HashMap;

const ROUNDING_SECONDS: i64 = 15 * 60;
const MINIMUM_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

/// Apply the invoice rules to one stopped entry.
pub fn billable_seconds(duration: i64) -> i64 {
    let rounded = ((duration + ROUNDING_SECONDS - 1) / ROUNDING_SECONDS) * ROUNDING_SECONDS;
    rounded.max(MINIMUM_SECONDS)
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let mut totals: HashMap<String, i64> = HashMap::new();

        for entry in entries {
            if entry.billable && !entry.is_running() && entry.stop.is_some() {
                let project = entry
                    .project
                    .as_ref()
                    .map(|project| project.name.clone())
                    .unwrap_or_else(|| "No Project".to_string());
                *totals.entry(project).or_default() += billable_seconds(entry.duration);
            }
        }

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let mut totals: Vec<_> = totals.into_iter().collect();
        totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
            right_seconds
                .cmp(left_seconds)
                .then_with(|| left_name.cmp(right_name))
        });
        let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

        for (project, seconds) in totals {
            println!("{seconds}s  {project}");
        }
        println!("{total_seconds}s  Total");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::billable_seconds;

    #[test]
    fn rounds_up_then_applies_minimum() {
        assert_eq!(billable_seconds(1), 1800);
        assert_eq!(billable_seconds(899), 1800);
        assert_eq!(billable_seconds(900), 1800);
        assert_eq!(billable_seconds(901), 1800);
        assert_eq!(billable_seconds(1800), 1800);
        assert_eq!(billable_seconds(1801), 2700);
    }
}
